function consumeGarden(input, use, now) {
	if (use !== "easels" && use !== "hampers" && use !== "commission") return null;
	const s = settleGarden(input, now), radishes = use === "hampers" ? 2 : use === "commission" ? 1 : 0, flowers = use === "commission" ? 0 : 1;
	if (s.produce.radish < radishes || s.produce.marigold < flowers) return null;
	s.produce.radish -= radishes;
	s.produce.marigold -= flowers;
	s.consumed[use].radish += radishes;
	s.consumed[use].marigold += flowers;
	return gardenSchema.safeParse(s).success ? s : null;
}

function settleGarden(input, now) {
	gardenSchema.parse(input);
	nowSchema.parse(now);
	if (now < input.observedAt) throw new Error("Garden time moved backwards.");
	const s = structuredClone(input);
	s.observedAt = now;
	for (const [name, cap, period] of [[
		"clippings",
		GARDEN_RULES.clippingCap,
		GARDEN_RULES.clippingMs
	], [
		"rested",
		GARDEN_RULES.restedCap,
		GARDEN_RULES.restedMs
	]]) {
		const value = s[name], earned = Math.floor((now - value.lastAt) / period);
		// No fractional or hidden reserve accumulates while the bank is already full.
		if (value.available === cap) {
			value.lastAt = now;
			continue;
		}
		if (earned > 0) {
			value.available = Math.min(cap, value.available + earned);
			value.lastAt = value.available === cap ? now : value.lastAt + earned * period;
		}
	}
	return s;
}

function applyGarden(input, raw, now) {
	const fail = (message) => ({
		ok: false,
		state: input,
		message,
		publicChanged: false,
		requestCredit: false
	});
	gardenSchema.parse(input);
	if (!nowSchema.safeParse(now).success || now < input.observedAt) return fail("The garden clock could not be confirmed. Your patch is unchanged.");
	const parsed = gardenActionSchema.safeParse(raw);
	if (!parsed.success) return fail("That garden request is not valid. Nothing changed.");
	const a = parsed.data, s = settleGarden(input, now);
	let message = "", requestCredit = false;
	if (a.action === "plant") {
		if (s.beds[a.bed]) return fail("This bed already has a plant. It has established tenancy.");
		if (s.seeds[a.crop] < 1) return fail("No bound seed of that kind is available. Growing plants count toward your starter supply.");
		const teaching = a.crop === "radish" && !s.firstRadishUsed;
		s.seeds[a.crop]--;
		s.planted++;
		s.beds[a.bed] = {
			crop: a.crop,
			plantedAt: now,
			readyAt: now + (teaching ? GARDEN_RULES.firstRadishMs : CROP_DEFS[a.crop].durationMs),
			cared: false
		};
		if (a.crop === "radish") s.firstRadishUsed = true;
		message = teaching ? "First radish planted — five real minutes. Later radishes take thirty. The committee has approved having roots." : "Planted. It grows while you are away and waits safely when ready.";
	} else if (a.action === "harvest") {
		const b = s.beds[a.bed];
		if (!b) return fail("There is no crop in this bed. The soil is considering its options.");
		if (b.readyAt > now) return fail("This crop is still growing. No extra attendance is required.");
		if (s.produce[b.crop] >= GARDEN_RULES.stack) return fail(`${CROP_DEFS[b.crop].name}: storage is full. Use a mixed request or another ready bed. This plant and seed will wait.`);
		s.produce[b.crop]++;
		s.seeds[b.crop]++;
		s.harvested[b.crop]++;
		s.practice++;
		if (s.rested.available > 0) {
			s.rested.available--;
			s.practice++;
			s.bonusPractice++;
		}
		s.beds[a.bed] = null;
		message = "Harvested one produce and returned one bound seed. Promoted to vegetable management.";
	} else if (a.action === "observe") {
		const b = s.beds[a.bed];
		if (!b) return fail("Plant a seed here before inspecting it.");
		if (b.cared) return fail("Already inspected this cycle. The plant has no further questions.");
		b.cared = true;
		message = "Soil checked, leaves admired. No speed or yield bonus — just a well-informed gardener.";
	} else if (a.action === "recover-seeds") {
		let restored = 0;
		for (const crop of CROP_IDS) {
			const missing = CROP_DEFS[crop].seedQuota - s.seeds[crop] - s.beds.filter((b) => b?.crop === crop).length;
			s.seeds[crop] += missing;
			restored += missing;
		}
		if (!restored) return fail("Your starter seeds are all accounted for, including growing and ready plants.");
		message = "Missing bound starter seeds replaced. The library has declined to issue duplicate plants.";
	} else if (a.action === "make-marker") {
		if (s.markers.includes(a.marker)) return fail("You already own this marker. Choose it for display whenever you like.");
		if (s.clippings.available < GARDEN_RULES.markerCost) return fail("The field needs time to replenish clippings. Your workshop materials are untouched.");
		s.clippings.available -= GARDEN_RULES.markerCost;
		s.markers.push(a.marker);
		message = "Two field clippings gathered and made into a new marker by hand. Choose Display marker to share it.";
	} else if (a.action === "display-marker") {
		if (a.marker !== null && !s.markers.includes(a.marker)) return fail("You do not own that marker yet.");
		if (a.marker === s.selectedMarker) return fail("That display choice is already saved.");
		s.selectedMarker = a.marker;
		message = a.marker === null ? "Public marker removed. Your owned designs remain." : "Public marker selected. Only this chosen design is shared; your garden stock stays private.";
	} else if (a.action === "swap-beds") {
		if (a.from === a.to) return fail("Choose two different beds to rearrange.");
		[s.beds[a.from], s.beds[a.to]] = [s.beds[a.to], s.beds[a.from]];
		message = "Beds rearranged for free. Plants keep their original deadlines.";
	} else if (a.action === "accept-errand") {
		if (s.errand.accepted) return fail("The almost-straight-stakes errand is already in your journal.");
		s.errand.accepted = true;
		message = "An urgent matter of almost-straight stakes: inspect three marked pieces, then assemble your marker by hand. No timer or workshop materials.";
	} else if (a.action === "inspect-stake") {
		if (!s.errand.accepted) return fail("Accept the stake errand at the allotment first.");
		if (s.errand.pieces.includes(a.station)) return fail("This piece is already recorded. Three different pieces are needed.");
		if (STAKE_STUDIES[a.station].answer !== a.choice) return fail(STAKE_STUDIES[a.station].hint);
		s.errand.pieces.push(a.station);
		message = s.errand.pieces.length === 3 ? "Three usable pieces found. Return to assemble one entirely adequate marker." : "Usable stake piece recorded. It is quest material, not timber.";
	} else if (a.action === "assemble-marker") {
		if (s.errand.assembled) return fail("Your almost-straight marker is already owned and can be selected again.");
		if (!s.errand.accepted || s.errand.pieces.length !== 3) return fail("Inspect all three different stake pieces before assembling the marker.");
		s.errand.assembled = true;
		s.markers.push("almost-straight");
		message = "Officially almost straight: your new marker is owned. Choose Display marker to share it. No XP, money or workshop materials changed.";
	} else {
		if (s.nextRequestAt !== null && now < s.nextRequestAt) return fail("The mixed produce request is on its real twenty-four-hour cooldown. Your produce stays here.");
		if (s.produce.radish < 1 || s.produce.marigold < 1) return fail("This request needs one radish and one marigold. No one is taking your seeds.");
		s.produce.radish--;
		s.produce.marigold--;
		s.requests++;
		s.nextRequestAt = now + GARDEN_RULES.requestMs;
		requestCredit = true;
		message = "One radish and one marigold contributed. A public improvement, suspiciously improved by the public.";
	}
	if (!gardenSchema.safeParse(s).success) return fail("The prototype garden limit was reached. Your patch is unchanged.");
	return {
		ok: true,
		state: s,
		message,
		publicChanged: s.selectedMarker !== input.selectedMarker,
		requestCredit
	};
}

function nextGardenDeadline(s, now) {
	s = settleGarden(s, now);
	const candidates = [...s.beds.flatMap((b) => b && b.readyAt > now ? [b.readyAt] : []), ...s.nextRequestAt !== null && s.nextRequestAt > now ? [s.nextRequestAt] : []];
	if (s.clippings.available < GARDEN_RULES.clippingCap) candidates.push(s.clippings.lastAt + GARDEN_RULES.clippingMs);
	if (s.rested.available < GARDEN_RULES.restedCap) candidates.push(s.rested.lastAt + GARDEN_RULES.restedMs);
	const future = candidates.filter((t) => t > now);
	return future.length ? Math.min(...future) : null;
}

function applyCarpentry(input, garden, raw, now) {
	const fail = (message) => ({
		ok: false,
		state: input,
		garden,
		message,
		awardEasel: false,
		recordIntent: false
	});
	if (!carpentrySchema.safeParse(input).success || !gardenSchema.safeParse(garden).success || !carpentryLedgerMatches(input, garden)) return fail("The saved crafting ledger could not be confirmed. Nothing changed.");
	if (!clock.safeParse(now).success || now < input.observedAt || now < garden.observedAt) return fail("The crafting clock could not be confirmed. Nothing changed.");
	const parsed = carpentryActionSchema.safeParse(raw);
	if (!parsed.success) return fail("That carpentry request is not valid. Nothing changed.");
	const a = parsed.data, s = settleCarpentry(input, now);
	let g = garden, message = "", awardEasel = false, recordIntent = false;
	if (a.action === "learn-saw") {
		if (s.lessonAt !== null) return fail("Your practical lesson is already recorded. A missing bound saw can be recovered for free.");
		s.lessonAt = now;
		s.saw.owned = true;
		message = "Bound hand saw received. Equip it explicitly to prepare fallen pine. Certified to divide one problem into two smaller problems.";
	} else if (a.action === "recover-saw") {
		if (s.lessonAt === null) return fail("Complete the free practical lesson before recovering a saw.");
		if (s.saw.owned) return fail("Your bound saw is already accounted for. There is no spare saleable copy.");
		s.saw.owned = true;
		s.saw.equipped = false;
		message = "Missing bound saw replaced for free. Equip it when you are ready.";
	} else if (a.action === "equip-saw") {
		if (!s.saw.owned) return fail("Receive or recover your bound saw first.");
		if (s.saw.equipped === a.equipped) return fail("That equipment choice is already saved.");
		s.saw.equipped = a.equipped;
		message = a.equipped ? "Hand saw equipped. Fallen pine can now be prepared; no output multiplier." : "Hand saw put away. Your tool and materials remain yours.";
	} else if (a.action === "gather-pine") {
		if (!s.saw.equipped) return fail("Equip your bound hand saw before preparing fallen pine.");
		const quantity = Math.min(s.pine.available, CARPENTRY_RULES.carriedCap - s.pine.carried);
		if (!quantity) return fail(s.pine.carried === CARPENTRY_RULES.carriedCap ? "Pine storage is full (24). Use some at the finishing rack or in a hamper." : "Your personal pine pool is recovering: one bundle every four real hours, up to six. All three points share this supply.");
		s.pine.available -= quantity;
		s.pine.carried += quantity;
		s.pine.gathered += quantity;
		message = `Prepared ${quantity} pine. ${s.pine.carried}/24 carried. The three deadfall points share one personal supply; other residents keep theirs.`;
	} else if (a.action === "start-easel") {
		if (!s.saw.equipped) return fail("Equip your bound saw before starting the easel.");
		if (s.job) return fail("The finishing rack already has a job. Its easel waits safely for collection.");
		if (s.produced >= CARPENTRY_RULES.easelCap) return fail("Easel storage is full (99). No ingredients were spent.");
		if (s.pine.carried < 4) return fail("This easel needs four pine bundles and one marigold.");
		const spent = consumeGarden(garden, "easels", now);
		if (!spent) return fail("Keep one harvested marigold for this easel. Seeds and growing plants cannot be spent.");
		g = spent;
		s.pine.carried -= 4;
		s.pine.spent += 4;
		s.started++;
		s.job = {
			startedAt: now,
			readyAt: now + CARPENTRY_RULES.easelMs
		};
		message = "Garden study easel started: 4 pine + 1 marigold spent. Twelve real hours at its own rack; your ordinary bench stays available.";
	} else if (a.action === "claim-easel") {
		if (!s.job) return fail("There is no easel to collect.");
		if (s.job.readyAt > now) return fail("The easel is still finishing. Its original deadline is unchanged.");
		if (s.produced >= CARPENTRY_RULES.easelCap) return fail("Easel storage is full (99). Your finished job is kept.");
		s.job = null;
		s.produced++;
		s.practice += 3;
		awardEasel = true;
		message = "Collected a Garden study easel. +3 carpentry practice. Keep it, place it, or separately record its craft for the noticeboard without giving it away.";
	} else if (a.action === "deliver-hamper") {
		if (s.nextHamperAt !== null && s.nextHamperAt > now) return fail("The groundskeeper hamper is on its four-hour cooldown. Nothing was spent.");
		if (s.pine.carried < 1) return fail("The hamper needs 1 pine, 2 radishes and 1 marigold.");
		const spent = consumeGarden(garden, "hampers", now);
		if (!spent) return fail("The hamper needs 1 pine, 2 radishes and 1 marigold. Seeds and plants are kept.");
		g = spent;
		s.pine.carried--;
		s.pine.spent++;
		s.hampers++;
		s.practice++;
		s.nextHamperAt = now + CARPENTRY_RULES.hamperMs;
		message = "Hamper delivered: 1 pine, 2 radishes and 1 marigold spent. +1 private carpentry practice. Locally sourced. Extensively documented.";
	} else if (a.action === "record-easel") {
		if (s.recorded >= s.produced) return fail("No unrecorded completed easel is available. Each craft can be recorded once, and its item stays yours.");
		s.recorded++;
		if (s.recorded === 6) s.sixthRecordAt = now;
		recordIntent = true;
		message = "Craft recorded. You keep your easel. The town service confirms whether this adds a noticeboard credit.";
	} else {
		if (s.keepEaselGoal === a.enabled) return fail("That planning choice is already saved.");
		s.keepEaselGoal = a.enabled;
		message = a.enabled ? "Easel goal shown: plan to keep 4 pine and 1 marigold. This is an aid, not an inventory lock." : "Easel goal hidden. Nothing was spent or reserved.";
	}
	if (!carpentrySchema.safeParse(s).success || !carpentryLedgerMatches(s, g)) return fail("This request would exceed a prototype limit. Nothing changed.");
	return {
		ok: true,
		state: s,
		garden: g,
		message,
		awardEasel,
		recordIntent
	};
}

function applyCommission(input, carpentry, garden, raw, now) {
	const fail = (message) => ({
		ok: false,
		state: input,
		carpentry,
		garden,
		message
	});
	if (!commissionSchema.safeParse(input).success || !carpentrySchema.safeParse(carpentry).success || !gardenSchema.safeParse(garden).success || !commissionLedgerMatches(input, carpentry, garden)) return fail("The commission ledger could not be confirmed. Nothing changed.");
	if (!clock.safeParse(now).success || now < carpentry.observedAt || now < garden.observedAt || input.acceptedAt !== null && now < input.acceptedAt || input.completedAt !== null && now < input.completedAt) return fail("The confirmed clock moved backwards. Your route is kept.");
	const parsed = commissionActionSchema.safeParse(raw);
	if (!parsed.success) return fail("That post request is not valid. Nothing changed.");
	const a = parsed.data, c = structuredClone(input);
	let p = carpentry, g = garden, message = "";
	if (a.action === "accept") {
		if (c.acceptedAt !== null) return fail("Your original parcels and receipts are already kept. Resume the same route.");
		c.acceptedAt = now;
		message = "Three addressed parcels accepted. No bag space, payment or deadline. The route is circular. For once, this is intentional.";
	} else if (a.action === "pause") {
		if (c.acceptedAt === null || c.completedAt !== null || c.paused === a.paused) return fail("There is no change to make to this route.");
		c.paused = a.paused;
		message = a.paused ? "Route paused. The same parcels and receipts stay kept; nothing expires." : "Same route resumed. No replacement parcels or duplicate receipts were issued.";
	} else if (a.action === "handover") {
		if (c.acceptedAt === null || c.completedAt !== null) return fail("Accept Pip’s route before delivering an outstanding parcel.");
		if (c.paused) return fail("Resume your kept route with Pip before handing over a parcel.");
		if (c.order.includes(a.parcel)) return fail("That parcel already has its receipt. No duplicate was issued.");
		if (a.parcel !== a.recipient) return fail(RECIPIENTS[a.recipient].name + " returns the same parcel for " + RECIPIENTS[a.parcel].name + ". Nothing is lost.");
		c.order.push(a.parcel);
		message = RECIPIENTS[a.parcel].reply + " Receipt kept.";
	} else if (a.action === "complete") {
		if (c.acceptedAt === null || c.paused || c.order.length !== 3 || c.completedAt !== null) return fail("Bring all three unique receipts to Pip on your active route.");
		c.completedAt = now;
		message = "Route card and letterbox plan saved. Everything arrived. The town is choosing to regard this as a precedent. A physical letterbox is optional and made separately.";
	} else if (a.action === "make") {
		if (c.completedAt === null) return fail("Complete the free route for the letterbox plan first.");
		if (c.madeCount !== 0) return fail("Your one letterbox is already owned. Move it or change its motif for free.");
		if (carpentry.pine.carried < 2 || garden.produce.radish < 1) return fail("Need 2 carried pine + 1 harvested radish. Seeds and growing crops are kept. Nothing was spent.");
		const debit = consumeGarden(garden, "commission", now);
		if (!debit) return fail("The harvested radish could not be confirmed. Nothing was spent.");
		g = debit;
		p = structuredClone(carpentry);
		p.observedAt = now;
		p.pine.carried -= 2;
		p.pine.spent += 2;
		p.commissionPine += 2;
		c.madeCount = 1;
		c.motif = a.motif;
		message = "Made one Unreasonably Official Letterbox: 2 pine + 1 radish spent once. No new timer or production bonus. Motif changes and moving this same item are free.";
	} else if (a.action === "style") {
		if (c.madeCount !== 1) return fail("Make your one physical letterbox before changing its motif.");
		if (c.motif === a.motif) return fail("That motif is already saved. Nothing was spent.");
		c.motif = a.motif;
		message = "Letterbox motif changed for free. Same owned item, same placements.";
	} else {
		if (c.madeCount !== 1) return fail("Make the physical letterbox before publishing its style sample.");
		if (c.published === a.enabled) return fail("That publication choice is already saved.");
		c.published = a.enabled;
		message = a.enabled ? "Your name and chosen motif are shown at Pip’s sample register. Private deliveries and stock stay private; no extra item was created." : "Style sample removed. Your letterbox, motif and placement stay yours.";
	}
	if (!commissionSchema.safeParse(c).success || !carpentrySchema.safeParse(p).success || !gardenSchema.safeParse(g).success || !commissionLedgerMatches(c, p, g)) return fail("This request would create invalid commission progress. Nothing changed.");
	return {
		ok: true,
		state: c,
		carpentry: p,
		garden: g,
		message
	};
}

function settleWorkshop(input, now) {
	if (!validTime(now) || now < input.observedAt) return input;
	let next;
	for (const resource of RESOURCE_IDS) {
		const node = input.nodes[resource];
		if (node.stock >= NODE_CAPACITY) continue;
		const elapsed = Math.min(now - node.lastAt, OFFLINE_CAP_MS);
		const earned = Math.floor(elapsed / REGEN_MS);
		if (!earned) continue;
		next ??= structuredClone(input);
		const stock = Math.min(NODE_CAPACITY, node.stock + earned);
		next.nodes[resource] = {
			stock,
			lastAt: stock === NODE_CAPACITY ? now : now - elapsed % REGEN_MS
		};
	}
	if (next) next.observedAt = now;
	return next ?? input;
}

function applyWorkshop(input, raw, now, allocatedElsewhere = {}) {
	const fail = (message) => ({
		state: input,
		ok: false,
		message,
		replayed: false
	});
	if (!stateSchema.safeParse(input).success) return fail("The saved workshop could not be validated. Nothing was changed.");
	if (Object.keys(allocatedElsewhere).some((id) => !PROP_IDS.includes(id)) || PROP_IDS.some((id) => {
		const n = allocatedElsewhere[id] ?? 0;
		return !Number.isInteger(n) || n < 0 || n > ITEM_LIMIT || n + Object.values(input.placements).filter((p) => p === id).length > input.owned[id];
	})) return fail("Furniture allocation could not be confirmed. Nothing was moved.");
	const parsed = commandSchema.safeParse(raw);
	if (!parsed.success) return fail("That request is not valid. Nothing was changed.");
	if (!validTime(now) || now < input.observedAt) return fail("The local clock moved backwards. Try again when it catches up.");
	const cmd = parsed.data, receipt = input.receipts.find((r) => r.id === cmd.id);
	if (receipt) return {
		state: input,
		ok: true,
		message: receipt.message,
		replayed: true
	};
	if (cmd.expectedRevision !== input.revision) return fail("Your bag changed. Review it and try again.");
	if (input.revision >= 1e6) return fail("This prototype has reached its command limit. Your progress is safe; no change was made.");
	const next = structuredClone(settleWorkshop(input, now));
	let message = "";
	if (cmd.kind === "commission") {
		const applied = applyCommission(next.commission, next.carpentry, next.garden, cmd.commissionAction, now);
		if (!applied.ok) return fail(applied.message);
		next.commission = applied.state;
		next.carpentry = applied.carpentry;
		next.garden = applied.garden;
		next.owned.letterbox = applied.state.madeCount;
		message = applied.message;
	} else if (cmd.kind === "carpentry") {
		const applied = applyCarpentry(next.carpentry, next.garden, cmd.carpentryAction, now);
		if (!applied.ok) return fail(applied.message);
		next.carpentry = applied.state;
		next.garden = applied.garden;
		if (applied.awardEasel) next.owned.easel++;
		message = applied.message;
	} else if (cmd.kind === "garden") {
		const applied = applyGarden(next.garden, cmd.gardenAction, now);
		if (!applied.ok) return fail(applied.message);
		next.garden = applied.state;
		message = applied.message;
	} else if (cmd.kind === "survey") {
		if (next.sketches.includes(cmd.station)) return fail("Already recorded. Your sketch is still here; the tree has nothing to add.");
		if (cmd.choice !== SURVEYS[cmd.station].answer) return fail("Take another look at the tree or read the observation hint. Nothing was spent or changed.");
		next.sketches.push(cmd.station);
		message = next.sketches.length === SURVEY_IDS.length ? "Three studies recorded. Your Neighborhood Naturalist keepsake is saved in your sketchbook. The trees have issued you a reference." : "Tree study recorded. A useful observation. The committee is visibly relieved.";
	} else if (cmd.kind === "gather") {
		const node = next.nodes[cmd.resource];
		const room = STORAGE_LIMIT - RESOURCE_IDS.reduce((n, id) => n + next.inventory[id], 0);
		const quantity = Math.min(node.stock, room);
		if (!quantity) return fail(room ? "This bin is recovering. One material returns every four hours, up to six." : "Your material bag is full (60). Use materials at the bench first.");
		if (next.stats.gathered + quantity > 1e6 || next.skills.gathering + quantity > 1e6) return fail("The prototype skill counter is full. Nothing was changed.");
		if (node.stock === NODE_CAPACITY) node.lastAt = now;
		node.stock -= quantity;
		next.inventory[cmd.resource] += quantity;
		next.stats.gathered += quantity;
		next.skills.gathering += quantity;
		message = `Gathered ${quantity} ${cmd.resource}. ${node.stock} left in the bin.`;
	} else if (cmd.kind === "craft") {
		if (next.job) return fail("The bench already has a job. Collect it before starting another.");
		if (cmd.recipe === "bridge-kit" && !next.stats.planterPlacedAfterCraft) return fail("Make and place your first planter before taking committee work.");
		const recipe = RECIPES[cmd.recipe];
		if (RESOURCE_IDS.some((id) => next.inventory[id] < recipe.cost[id])) return fail("Not enough materials. The recipe lists exactly what you need.");
		const output = cmd.recipe === "planter" ? next.owned.planter : next.bridgeKits;
		if (output >= ITEM_LIMIT) return fail("Output storage is full (99). No materials were spent.");
		if (cmd.recipe === "bridge-kit" && next.stats.bridgeJobsStarted >= 1e6) return fail("The prototype counter is full. No materials were spent.");
		for (const id of RESOURCE_IDS) next.inventory[id] -= recipe.cost[id];
		next.job = {
			recipe: cmd.recipe,
			startedAt: now,
			readyAt: now + recipeDuration(next, cmd.recipe)
		};
		if (cmd.recipe === "bridge-kit") next.stats.bridgeJobsStarted++;
		message = `${recipe.name} started. Materials spent: ${recipe.cost.scrap} scrap, ${recipe.cost.timber} timber, ${recipe.cost.supplies} supplies.`;
	} else if (cmd.kind === "claim") {
		if (!next.job) return fail("There is no job to collect.");
		if (now < next.job.readyAt) return fail("The job is still working. Its remaining time is shown at the bench.");
		if (next.stats.crafted >= 1e6 || next.skills.making >= 1e6) return fail("The prototype skill counter is full. Your job is waiting safely.");
		if (next.job.recipe === "planter") {
			if (next.owned.planter >= ITEM_LIMIT || next.stats.plantersCrafted >= 1e6) return fail("Planter storage is full. Your finished job is waiting.");
			next.owned.planter++;
			next.stats.plantersCrafted++;
		} else {
			if (next.bridgeKits >= ITEM_LIMIT) return fail("Kit storage is full. Your finished job is waiting.");
			next.bridgeKits++;
		}
		message = `Collected one ${RECIPES[next.job.recipe].name.toLowerCase()}. +1 Making experience.`;
		next.job = null;
		next.stats.crafted++;
		next.skills.making++;
	} else if (cmd.kind === "place") {
		if (next.placements[cmd.slot]) return fail("That nook is occupied. Choose an empty nook or remove its furniture first.");
		if (cmd.fromSlot && next.placements[cmd.fromSlot] !== cmd.prop) return fail("The furniture to move is no longer there.");
		const used = Object.values(next.placements).filter((prop) => prop === cmd.prop).length + (allocatedElsewhere[cmd.prop] ?? 0);
		if (!cmd.fromSlot && used >= next.owned[cmd.prop]) return fail("You do not own an unplaced copy of this furnishing.");
		if (next.stats.placed >= 1e6) return fail("The prototype placement counter is full. Nothing was moved.");
		if (cmd.fromSlot) next.placements[cmd.fromSlot] = null;
		next.placements[cmd.slot] = cmd.prop;
		next.stats.placed++;
		if (cmd.prop === "planter" && next.stats.plantersCrafted > 0) next.stats.planterPlacedAfterCraft = true;
		message = `${PROPS[cmd.prop].name} ${cmd.fromSlot ? "moved" : "placed"}. No materials spent.`;
	} else {
		if (!next.placements[cmd.slot]) return fail("That nook is already empty.");
		message = `${PROPS[next.placements[cmd.slot]].name} returned to your bag. No materials spent.`;
		next.placements[cmd.slot] = null;
	}
	next.revision++;
	next.observedAt = now;
	next.lastMessage = message;
	next.receipts.push({
		id: cmd.id,
		revision: next.revision,
		message
	});
	next.receipts = next.receipts.slice(-64);
	// Reject overflow or an invariant failure atomically, including malformed future content.
	if (!stateSchema.safeParse(next).success) return fail("This request would create invalid progress. Nothing was changed.");
	return {
		state: next,
		ok: true,
		message,
		replayed: false
	};
}

function recipeDuration(state, recipe) {
	return recipe === "planter" && state.stats.plantersCrafted === 0 ? RECIPES.planter.tutorialDurationMs : RECIPES[recipe].durationMs;
}

function questStep(state) {
	if (!state.stats.plantersCrafted && !state.job && RESOURCE_IDS.some((id) => state.inventory[id] < RECIPES.planter.cost[id])) return {
		id: "gather",
		title: "Something from almost nothing",
		detail: "Tap a material bin in the square. Gather scrap, timber and supplies for your first planter.",
		complete: false
	};
	if (!state.stats.plantersCrafted) return {
		id: "craft",
		title: "A remarkably short apprenticeship",
		detail: "At the workshop bench, make and collect your first planter. This first lesson takes five seconds; later planters take eight hours.",
		complete: false
	};
	if (!state.stats.planterPlacedAfterCraft) return {
		id: "place",
		title: "Put down a very small root",
		detail: "Open your bag and place your new planter in a workshop nook. Previewing and moving furniture are free.",
		complete: false
	};
	if (!state.stats.bridgeJobsStarted) return {
		id: "bridge",
		title: "The committee requests a kit",
		detail: "Gather more materials and start a twelve-hour bridge kit at the bench. It will wait for you; no need to keep this tab open.",
		complete: false
	};
	return {
		id: "complete",
		title: "Orientation postponed. Again.",
		detail: "First lesson complete. Your queued job and furnishings stay saved. Bridge donations and plot ownership are available in shared practice, which keeps a separate save.",
		complete: true
	};
}
